{"CommandLine":"powershell -Command "
# 1. Kill AI_BS_Backend parent processes first so watchdog stops auto-restarting daemons
Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -like '*AI_BS_Backend*' } | ForEach-Object {
    Write-Host 'Terminating Master Backend Parent PID' $_.ProcessId;
    Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
}

Start-Sleep -Seconds 1

# 2. Kill all child daemon processes
Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -like '*_daemon*' -or $_.CommandLine -like '*chroma*' } | ForEach-Object {
    Write-Host 'Terminating Daemon PID' $_.ProcessId;
    Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
}
"","Cwd":"c:\AI-BS","WaitMsBeforeAsync":5000,"toolAction":"Stopping parent master process and child daemons","toolSummary":"Stop master backend parent and child daemons"}
